<!-- src/components/PlayerBar.vue -->
<template>
  <div class="player-bar">
    <button v-if="currentSong" class="now-track" @click="npVisible = true" aria-label="Mở trình phát toàn màn hình">
      <div class="mini-art" :class="{ spinning: isPlaying }"><img :src="currentSong.cover" :alt="currentSong.title" /><span class="mini-art-ring"></span></div>
      <div class="track-details"><div class="track-title">{{ currentSong.title }}</div><div class="track-artist">{{ currentSong.artist }}</div></div><span class="expand-hint">↗</span>
    </button>
    <div v-else class="now-track empty"><div class="mini-art placeholder"><span>♪</span></div><div class="track-details"><div class="track-title muted">Chọn một bài để bắt đầu</div><div class="track-artist">LuNu Music · offline library</div></div></div>

    <div class="player-controls">
      <div class="control-row"><button class="icon-control optional" :class="{ active: isShuffle }" @click="emit('toggle-shuffle')" title="Phát ngẫu nhiên" aria-label="Phát ngẫu nhiên"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/></svg></button><button class="icon-control" @click="emit('prev')" :disabled="!currentSong" title="Bài trước" aria-label="Bài trước"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 5h2v14H6zM9 12l10-7v14z"/></svg></button><button class="play-btn" @click="togglePlay" :disabled="!currentSong" aria-label="Phát hoặc tạm dừng"><span v-if="isPlaying">Ⅱ</span><span v-else class="play-triangle">▶</span></button><button class="icon-control" @click="emit('next')" :disabled="!currentSong" title="Bài tiếp" aria-label="Bài tiếp"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M16 5h2v14h-2zM5 5l10 7-10 7z"/></svg></button><button class="icon-control optional" :class="{ active: repeatMode !== 'off' }" @click="emit('toggle-repeat')" title="Lặp lại" aria-label="Lặp lại"><span v-if="repeatMode === 'one'" class="repeat-one">1</span><svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m17 1 4 4-4 4"/><path d="M3 11V9a4 4 0 0 1 4-4h14M7 23l-4-4 4-4"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg></button></div>
      <div class="progress-container"><span class="time">{{ formatTime(currentTime) }}</span><input type="range" class="progress-bar" min="0" :max="duration || 0" v-model="currentTime" @input="seek" :disabled="!currentSong" :style="progressStyle" /><span class="time">{{ formatTime(duration) }}</span></div>
    </div>

    <div class="player-actions"><button class="queue-toggle" :class="{ active: showQueueHint }" @click="emit('toggle-queue')" title="Hàng đợi" aria-label="Hàng đợi"><span class="queue-lines"><i></i><i></i><i></i></span></button><button class="volume-icon" @click="toggleMute" title="Âm lượng" aria-label="Tắt hoặc bật tiếng">{{ volume > 0 ? '◖' : '○' }}</button><input type="range" class="volume-bar" min="0" max="1" step="0.01" v-model="volume" @input="updateVolume" :style="volumeStyle" /><span class="quality-pill">HI-FI</span></div>

    <audio ref="audioRef" :src="currentSong?.url" @timeupdate="onTimeUpdate" @loadedmetadata="onLoadedMetadata" @ended="onEnded"></audio>
    <NowPlayingView :visible="npVisible" :current-song="currentSong" :is-playing="isPlaying" :is-shuffle="isShuffle" :repeat-mode="repeatMode" :current-time="currentTime" :duration="duration" :visualizer-data="visualizerData" @close="npVisible = false" @toggle-play="togglePlay" @next="emit('next')" @prev="emit('prev')" @toggle-shuffle="emit('toggle-shuffle')" @toggle-repeat="emit('toggle-repeat')" @seek="seekTo" @manage-lyrics="manageLyrics" />
  </div>
</template>

<script setup>
import { ref, watch, computed, nextTick } from 'vue';
import NowPlayingView from './NowPlayingView.vue';
const props = defineProps({ currentSong: Object, isShuffle: Boolean, repeatMode: String });
const emit = defineEmits(['next', 'prev', 'toggle-shuffle', 'toggle-repeat', 'update:is-playing', 'toggle-queue', 'manage-lyrics']);
const audioRef = ref(null); const isPlaying = ref(false); const currentTime = ref(0); const duration = ref(0); const volume = ref(1); const previousVolume = ref(1); const npVisible = ref(false); const visualizerData = ref(new Array(24).fill(0)); const showQueueHint = ref(false);
const manageLyrics = () => { npVisible.value = false; emit('manage-lyrics'); };
const togglePlay = () => { if (!audioRef.value || !props.currentSong) return; if (isPlaying.value) { audioRef.value.pause(); isPlaying.value = false; emit('update:is-playing', false); } else { audioRef.value.play().then(() => { isPlaying.value = true; emit('update:is-playing', true); }).catch(() => {}); } };
watch(() => props.currentSong, async (song) => { if (!song) return; await nextTick(); currentTime.value = 0; duration.value = 0; audioRef.value?.play().then(() => { isPlaying.value = true; emit('update:is-playing', true); }).catch(() => {}); });
const onTimeUpdate = () => { if (audioRef.value) currentTime.value = audioRef.value.currentTime; };
const onLoadedMetadata = () => { if (audioRef.value) duration.value = audioRef.value.duration; };
const seek = () => { if (audioRef.value) audioRef.value.currentTime = currentTime.value; };
const seekTo = (value) => { currentTime.value = value; if (audioRef.value) audioRef.value.currentTime = value; };
const updateVolume = () => { if (!audioRef.value) return; audioRef.value.volume = volume.value; if (volume.value > 0) previousVolume.value = volume.value; };
const toggleMute = () => { volume.value = volume.value > 0 ? 0 : (previousVolume.value || 1); if (audioRef.value) audioRef.value.volume = volume.value; };
const onEnded = () => { if (props.repeatMode === 'one') { audioRef.value.currentTime = 0; audioRef.value.play(); } else emit('next'); };
const formatTime = (time) => { if (!time || Number.isNaN(time)) return '0:00'; const m = Math.floor(time / 60); const s = Math.floor(time % 60); return `${m}:${s < 10 ? '0' : ''}${s}`; };
const progressStyle = computed(() => ({ '--fill': duration.value ? `${(currentTime.value / duration.value) * 100}%` : '0%' }));
const volumeStyle = computed(() => ({ '--fill': `${volume.value * 100}%` }));
</script>

<style scoped>
.player-bar { display: flex; align-items: center; justify-content: space-between; gap: 24px; height: 100%; padding: 0 clamp(16px, 2.7vw, 38px); }.now-track { display: flex; align-items: center; min-width: 0; width: 29%; padding: 6px 8px; margin-left: -8px; border: 0; border-radius: 13px; background: transparent; text-align: left; cursor: pointer; }.now-track:hover { background: var(--glass); }.now-track.empty { cursor: default; }.mini-art { position: relative; width: 51px; height: 51px; flex: 0 0 auto; margin-right: 13px; border: 1px solid rgba(245,185,122,.35); border-radius: 13px; overflow: hidden; box-shadow: 0 8px 22px rgba(0,0,0,.25); }.mini-art.spinning { border-radius: 50%; animation: spin 7s linear infinite; }.mini-art img { width: 100%; height: 100%; object-fit: cover; }.mini-art-ring { position: absolute; inset: 5px; border: 1px solid rgba(255,255,255,.25); border-radius: inherit; }.mini-art.placeholder { display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, rgba(245,185,122,.15), rgba(155,140,255,.13)); color: var(--gold); font-size: 22px; }.track-details { min-width: 0; }.track-title { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 700; }.track-title.muted { color: var(--text-sub); }.track-artist { overflow: hidden; margin-top: 5px; color: var(--text-sub); text-overflow: ellipsis; white-space: nowrap; font-size: 10px; }.expand-hint { margin-left: 12px; color: var(--gold); opacity: 0; }.now-track:hover .expand-hint { opacity: 1; }.player-controls { display: flex; flex-direction: column; align-items: center; flex: 1; max-width: 560px; min-width: 260px; }.control-row { display: flex; align-items: center; gap: clamp(11px, 1.6vw, 23px); margin-bottom: 9px; }.icon-control, .queue-toggle, .volume-icon { display: flex; align-items: center; justify-content: center; width: 27px; height: 27px; padding: 0; border: 0; border-radius: 9px; background: transparent; color: var(--text-sub); cursor: pointer; }.icon-control svg { width: 16px; height: 16px; }.icon-control:hover, .icon-control.active, .queue-toggle:hover, .queue-toggle.active { color: var(--gold); background: rgba(245,185,122,.09); }.icon-control.active { color: var(--gold); }.repeat-one { font: 700 11px var(--font-mono); }.play-btn { display: flex; align-items: center; justify-content: center; width: 39px; height: 39px; border: 0; border-radius: 50%; background: linear-gradient(135deg, var(--gold-bright), var(--gold)); color: #161017; box-shadow: 0 7px 22px rgba(245,185,122,.2); cursor: pointer; font-size: 15px; }.play-btn:hover { transform: scale(1.08); box-shadow: 0 10px 29px rgba(245,185,122,.35); }.play-triangle { margin-left: 2px; }.progress-container { display: flex; align-items: center; width: 100%; gap: 10px; }.time { width: 34px; color: var(--text-faint); text-align: center; font: 9px var(--font-mono); }.progress-bar, .volume-bar { -webkit-appearance: none; appearance: none; height: 4px; border-radius: 999px; background: linear-gradient(to right, var(--gold) 0%, var(--gold) var(--fill, 0%), rgba(255,255,255,.11) var(--fill, 0%), rgba(255,255,255,.11) 100%); cursor: pointer; }.progress-bar { flex: 1; }.progress-bar::-webkit-slider-thumb, .volume-bar::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border: 2px solid var(--bg-deep); border-radius: 50%; background: var(--gold-bright); opacity: 0; transition: opacity .15s; }.progress-bar:hover::-webkit-slider-thumb, .volume-bar:hover::-webkit-slider-thumb { opacity: 1; }.player-actions { display: flex; align-items: center; justify-content: flex-end; gap: 7px; width: 29%; }.queue-lines { display: flex; flex-direction: column; gap: 3px; width: 15px; }.queue-lines i { display: block; width: 15px; height: 2px; border-radius: 5px; background: currentColor; }.queue-lines i:nth-child(2) { width: 10px; }.volume-icon { font-size: 19px; }.volume-bar { width: 82px; }.quality-pill { border: 1px solid rgba(130,229,195,.2); border-radius: 6px; padding: 4px 6px; color: var(--mint); font: 8px var(--font-mono); letter-spacing: .7px; }
@media (max-width: 760px) { .optional, .volume-bar, .volume-icon, .quality-pill { display: none; }.player-bar { gap: 12px; padding: 0 13px; }.now-track { width: auto; flex: 1; margin: 0; padding: 0; }.mini-art { width: 43px; height: 43px; margin-right: 9px; border-radius: 11px; }.track-title { font-size: 11px; }.track-artist { font-size: 9px; }.player-controls { min-width: 41px; max-width: none; flex: 0 0 auto; }.control-row { margin: 0; }.control-row .icon-control:not(:nth-child(4)) { display: none; }.control-row .icon-control:nth-child(4) { display: flex; }.play-btn { width: 42px; height: 42px; }.progress-container { display: none; }.player-actions { width: auto; }.expand-hint { display: none; } }
@media (max-width: 360px) { .track-artist { display: none; }.mini-art { width: 39px; height: 39px; } }
</style>
